// CRC32 table
fn make_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut c = i as u32;
        for _ in 0..8 {
            if c & 1 != 0 {
                c = 0xedb88320 ^ (c >> 1);
            } else {
                c >>= 1;
            }
        }
        table[i] = c;
    }
    table
}

fn crc32(data: &[u8], table: &[u32; 256]) -> u32 {
    let mut crc: u32 = 0xffffffff;
    for &b in data {
        crc = table[((crc ^ (b as u32)) & 0xff) as usize] ^ (crc >> 8);
    }
    crc ^ 0xffffffff
}

// SHA1 implementation
fn sha1(input: &[u8]) -> [u8; 20] {
    let mut h0: u32 = 0x67452301;
    let mut h1: u32 = 0xEFCDAB89;
    let mut h2: u32 = 0x98BADCFE;
    let mut h3: u32 = 0x10325476;
    let mut h4: u32 = 0xC3D2E1F0;

    let ml = (input.len() as u64) * 8;
    let mut padded = Vec::from(input);
    padded.push(0x80);
    while (padded.len() % 64) != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&ml.to_be_bytes());

    for chunk in padded.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = ((chunk[i*4] as u32) << 24) | ((chunk[i*4+1] as u32) << 16) | ((chunk[i*4+2] as u32) << 8) | (chunk[i*4+3] as u32);
        }
        for i in 16..80 {
            w[i] = (w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16]).rotate_left(1);
        }
        let mut a = h0;
        let mut b = h1;
        let mut c = h2;
        let mut d = h3;
        let mut e = h4;
        for i in 0..80 {
            let (f, k) = if i < 20 {
                ((b & c) | ((!b) & d), 0x5A827999)
            } else if i < 40 {
                (b ^ c ^ d, 0x6ED9EBA1)
            } else if i < 60 {
                ((b & c) | (b & d) | (c & d), 0x8F1BBCDC)
            } else {
                (b ^ c ^ d, 0xCA62C1D6)
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
        h4 = h4.wrapping_add(e);
    }
    let mut out = [0u8; 20];
    out[0..4].copy_from_slice(&h0.to_be_bytes());
    out[4..8].copy_from_slice(&h1.to_be_bytes());
    out[8..12].copy_from_slice(&h2.to_be_bytes());
    out[12..16].copy_from_slice(&h3.to_be_bytes());
    out[16..20].copy_from_slice(&h4.to_be_bytes());
    out
}

fn hmac_sha1(key: &[u8], data: &[u8]) -> [u8; 20] {
    let mut key_block = [0u8; 64];
    if key.len() > 64 {
        let h = sha1(key);
        key_block[..20].copy_from_slice(&h);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }
    let mut ipad = [0x36u8; 64];
    let mut opad = [0x5cu8; 64];
    for i in 0..64 {
        ipad[i] ^= key_block[i];
        opad[i] ^= key_block[i];
    }
    let mut inner = Vec::with_capacity(64 + data.len());
    inner.extend_from_slice(&ipad);
    inner.extend_from_slice(data);
    let inner_hash = sha1(&inner);
    let mut outer = Vec::with_capacity(64 + 20);
    outer.extend_from_slice(&opad);
    outer.extend_from_slice(&inner_hash);
    sha1(&outer)
}

fn pbkdf2_hmac_sha1(password: &[u8], salt: &[u8], iterations: u32, dklen: usize) -> Vec<u8> {
    let hlen = 20;
    let l = (dklen + hlen - 1) / hlen;
    let mut dk = Vec::with_capacity(l * hlen);
    for i in 1..=l {
        let mut salt_block = Vec::with_capacity(salt.len() + 4);
        salt_block.extend_from_slice(salt);
        salt_block.extend_from_slice(&(i as u32).to_be_bytes());
        let mut u = hmac_sha1(password, &salt_block);
        let mut t = u;
        for _ in 1..iterations {
            u = hmac_sha1(password, &u);
            for j in 0..hlen {
                t[j] ^= u[j];
            }
        }
        dk.extend_from_slice(&t);
    }
    dk.truncate(dklen);
    dk
}

// ZipCrypto
fn init_zip_keys(pwd: &[u8], table: &[u32; 256]) -> [u32; 3] {
    let mut k0: u32 = 0x12345678;
    let mut k1: u32 = 0x23456789;
    let mut k2: u32 = 0x34567890;
    for &b in pwd {
        k0 = table[((k0 ^ (b as u32)) & 0xff) as usize] ^ (k0 >> 8);
        k1 = k1.wrapping_add(k0 & 0xff).wrapping_mul(0x08088405).wrapping_add(1);
        k2 = table[((k2 ^ (k1 >> 24)) & 0xff) as usize] ^ (k2 >> 8);
    }
    [k0, k1, k2]
}

fn zip_decrypt_byte(keys: &[u32; 3]) -> u8 {
    let temp = keys[2] | 2;
    (((temp.wrapping_mul(temp ^ 1)) >> 8) & 0xff) as u8
}

fn zip_update_keys(keys: &mut [u32; 3], b: u8, table: &[u32; 256]) {
    keys[0] = table[((keys[0] ^ (b as u32)) & 0xff) as usize] ^ (keys[0] >> 8);
    keys[1] = keys[1].wrapping_add(keys[0] & 0xff).wrapping_mul(0x08088405).wrapping_add(1);
    keys[2] = table[((keys[2] ^ (keys[1] >> 24)) & 0xff) as usize] ^ (keys[2] >> 8);
}

// Zip structures
struct ZipEntryInfo {
    file_name: Vec<u8>,
    flag: u16,
    method: u16,
    crc: u32,
    comp_size: u32,
    uncomp_size: u32,
    local_offset: u32,
    mod_time: u16,
    mod_date: u16,
}

struct ZipFileData {
    entries: Vec<ZipEntryInfo>,
}

fn read_u16_le(data: &[u8], pos: usize) -> Option<u16> {
    if pos + 2 > data.len() { return None; }
    Some(u16::from_le_bytes([data[pos], data[pos+1]]))
}
fn read_u32_le(data: &[u8], pos: usize) -> Option<u32> {
    if pos + 4 > data.len() { return None; }
    Some(u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]))
}

fn parse_zip(data: &[u8]) -> Result<ZipFileData, String> {
    // Find EOCD: search backwards for PK\x05\x06
    if data.len() < 22 {
        return Err("Could not find EOCD".to_string());
    }
    let mut eocd_pos: Option<usize> = None;
    // EOCD can have comment up to 65535, so search last 65557 bytes
    let search_start = if data.len() > 65557 + 22 { data.len() - (65557 + 22) } else { 0 };
    for pos in (search_start..data.len().saturating_sub(4)).rev() {
        if data[pos] == 0x50 && data[pos+1] == 0x4b && data[pos+2] == 0x05 && data[pos+3] == 0x06 {
            // Check comment len matches
            if pos + 22 > data.len() { continue; }
            let comment_len = u16::from_le_bytes([data[pos+20], data[pos+21]]) as usize;
            if pos + 22 + comment_len == data.len() {
                eocd_pos = Some(pos);
                break;
            }
        }
    }
    let eocd_pos = match eocd_pos {
        Some(p) => p,
        None => return Err("Could not find EOCD".to_string()),
    };
    // Parse EOCD
    if eocd_pos + 22 > data.len() {
        return Err("Unexpected end of zip::spec::Zip32CDEBlock".to_string());
    }
    let disk_num = read_u16_le(data, eocd_pos+4).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_disk = read_u16_le(data, eocd_pos+6).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_entries_disk = read_u16_le(data, eocd_pos+8).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_entries_total = read_u16_le(data, eocd_pos+10).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_size = read_u32_le(data, eocd_pos+12).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_offset = read_u32_le(data, eocd_pos+16).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    // Ignore disk checks for simplicity (assume single disk)
    let _ = (disk_num, cd_disk, cd_entries_disk);
    let count = cd_entries_total as usize;
    let mut entries = Vec::new();
    let mut pos = cd_offset as usize;
    for _ in 0..count {
        if pos + 46 > data.len() {
            return Err("Unexpected end of zip::types::ZipCentralEntryBlock".to_string());
        }
        if !(data[pos]==0x50 && data[pos+1]==0x4b && data[pos+2]==0x01 && data[pos+3]==0x02) {
            return Err("Unexpected end of zip::types::ZipCentralEntryBlock".to_string());
        }
        let flag = read_u16_le(data, pos+8).unwrap();
        let method = read_u16_le(data, pos+10).unwrap();
        let mod_time = read_u16_le(data, pos+12).unwrap();
        let mod_date = read_u16_le(data, pos+14).unwrap();
        let crc = read_u32_le(data, pos+16).unwrap();
        let comp_size = read_u32_le(data, pos+20).unwrap();
        let uncomp_size = read_u32_le(data, pos+24).unwrap();
        let fn_len = read_u16_le(data, pos+28).unwrap() as usize;
        let extra_len = read_u16_le(data, pos+30).unwrap() as usize;
        let comment_len = read_u16_le(data, pos+32).unwrap() as usize;
        let local_offset = read_u32_le(data, pos+42).unwrap();
        if pos + 46 + fn_len + extra_len + comment_len > data.len() {
            return Err("Unexpected end of zip::types::ZipCentralEntryBlock".to_string());
        }
        let file_name = data[pos+46..pos+46+fn_len].to_vec();
        // skip extra and comment
        pos += 46 + fn_len + extra_len + comment_len;
        entries.push(ZipEntryInfo { file_name, flag, method, crc, comp_size, uncomp_size, local_offset, mod_time, mod_date });
    }
    Ok(ZipFileData { entries })
}

struct TargetFile {
    is_aes: bool,
    aes_strength: u8, // 1,2,3
    aes_method: u16, // original method
    salt: Vec<u8>,
    verif: [u8; 2],
    enc_data: Vec<u8>,
    auth: [u8; 10],
    // for zipcrypto
    flag: u16,
    method: u16,
    crc: u32,
    mod_time: u16,
    enc_bytes: Vec<u8>, // full encrypted bytes (header+data) for zipcrypto
    file_name_str: String,
}

fn get_target(data: &[u8], zip: &ZipFileData, file_number: usize) -> Result<TargetFile, String> {
    if file_number >= zip.entries.len() {
        return Err(format!("File number not found within archive error - '{}'", file_number));
    }
    let e = &zip.entries[file_number];
    let file_name_str = String::from_utf8_lossy(&e.file_name).to_string();
    if (e.flag & 0x1) == 0 {
        return Err(format!("Invalid zip file error - the selected file in the archive is not encrypted (file_number:{} file_name:{})", file_number, file_name_str));
    }
    // Check if AES (method 99)
    if e.method == 99 {
        // Need to parse local header to get extra and enc data
        let local_off = e.local_offset as usize;
        if local_off + 30 > data.len() {
            return Err("Invalid local file header".to_string());
        }
        if !(data[local_off]==0x50 && data[local_off+1]==0x4b && data[local_off+2]==0x03 && data[local_off+3]==0x04) {
            return Err("Invalid local file header".to_string());
        }
        let local_flag = read_u16_le(data, local_off+8).unwrap();
        let local_method = read_u16_le(data, local_off+10).unwrap();
        let _local_crc = read_u32_le(data, local_off+14).unwrap();
        let local_comp = read_u32_le(data, local_off+18).unwrap();
        let _local_uncomp = read_u32_le(data, local_off+22).unwrap();
        let fn_len = read_u16_le(data, local_off+26).unwrap() as usize;
        let extra_len = read_u16_le(data, local_off+28).unwrap() as usize;
        if local_off + 30 + fn_len + extra_len > data.len() {
            return Err("Invalid local file header".to_string());
        }
        let extra = &data[local_off+30+fn_len .. local_off+30+fn_len+extra_len];
        // Parse AES extra: find 0x9901
        let mut strength: Option<u8> = None;
        let mut aes_method: Option<u16> = None;
        let mut p = 0;
        while p + 4 <= extra.len() {
            let hid = u16::from_le_bytes([extra[p], extra[p+1]]);
            let sz = u16::from_le_bytes([extra[p+2], extra[p+3]]) as usize;
            if p + 4 + sz > extra.len() { break; }
            if hid == 0x9901 {
                if sz >= 7 {
                    // version 2 bytes, vendor 2 bytes, strength 1, method 2
                    let ver = u16::from_le_bytes([extra[p+4], extra[p+5]]);
                    let _vendor = &extra[p+6..p+8];
                    let s = extra[p+8];
                    let m = u16::from_le_bytes([extra[p+9], extra[p+10]]);
                    let _ = ver;
                    strength = Some(s);
                    aes_method = Some(m);
                }
                break;
            }
            p += 4 + sz;
        }
        let strength = strength.ok_or("Invalid AES extra".to_string())?;
        let aes_method = aes_method.unwrap_or(0);
        let salt_len = match strength { 1 => 8, 2 => 12, 3 => 16, _ => return Err("Invalid AES strength".to_string()) };
        // Use central's comp size? For AES, local comp should equal central comp? Use local_comp if non-zero else central?
        // Actually for descriptor, local may be 0. Use central if local is 0?
        let comp_size = if local_comp != 0 { local_comp } else { e.comp_size } as usize;
        let enc_start = local_off + 30 + fn_len + extra_len;
        if enc_start + comp_size > data.len() {
            return Err("Invalid AES data".to_string());
        }
        let enc = &data[enc_start .. enc_start+comp_size];
        if enc.len() < salt_len + 2 + 10 {
            return Err("Invalid AES data".to_string());
        }
        let salt = enc[..salt_len].to_vec();
        let verif = [enc[salt_len], enc[salt_len+1]];
        let auth_start = enc.len() - 10;
        let enc_data = enc[salt_len+2 .. auth_start].to_vec();
        let mut auth = [0u8; 10];
        auth.copy_from_slice(&enc[auth_start..]);
        let _ = (local_flag, local_method);
        Ok(TargetFile { is_aes: true, aes_strength: strength, aes_method, salt, verif, enc_data, auth, flag: e.flag, method: e.method, crc: e.crc, mod_time: e.mod_time, enc_bytes: Vec::new(), file_name_str })
    } else {
        // ZipCrypto
        let local_off = e.local_offset as usize;
        if local_off + 30 > data.len() {
            return Err("Invalid local file header".to_string());
        }
        if !(data[local_off]==0x50 && data[local_off+1]==0x4b && data[local_off+2]==0x03 && data[local_off+3]==0x04) {
            return Err("Invalid local file header".to_string());
        }
        let _local_flag = read_u16_le(data, local_off+8).unwrap();
        let _local_method = read_u16_le(data, local_off+10).unwrap();
        let local_crc = read_u32_le(data, local_off+14).unwrap();
        let local_comp = read_u32_le(data, local_off+18).unwrap();
        let _local_uncomp = read_u32_le(data, local_off+22).unwrap();
        let fn_len = read_u16_le(data, local_off+26).unwrap() as usize;
        let extra_len = read_u16_le(data, local_off+28).unwrap() as usize;
        let local_mod_time = read_u16_le(data, local_off+12).unwrap();
        if local_off + 30 + fn_len + extra_len > data.len() {
            return Err("Invalid local file header".to_string());
        }
        // Determine comp size: if data descriptor (flag bit 3), local sizes are 0, use central
        let use_descriptor = (e.flag & 0x8) != 0;
        let comp_size = if use_descriptor || local_comp == 0 { e.comp_size } else { local_comp } as usize;
        let crc_val = if use_descriptor || local_crc == 0 { e.crc } else { local_crc };
        // For descriptor, header check uses time, not crc. Need mod_time: use local or central? Use e.mod_time? Both should match? Use e.mod_time
        let enc_start = local_off + 30 + fn_len + extra_len;
        if enc_start + comp_size > data.len() {
            return Err("Invalid ZipCrypto data".to_string());
        }
        let enc_bytes = data[enc_start .. enc_start+comp_size].to_vec();
        let _ = local_mod_time;
        Ok(TargetFile { is_aes: false, aes_strength: 0, aes_method: 0, salt: Vec::new(), verif: [0,0], enc_data: Vec::new(), auth: [0;10], flag: e.flag, method: e.method, crc: crc_val, mod_time: e.mod_time, enc_bytes, file_name_str })
    }
}

fn check_zipcrypto(pwd: &[u8], target: &TargetFile, crc_table: &[u32; 256]) -> bool {
    if target.enc_bytes.len() < 12 {
        return false;
    }
    let mut keys = init_zip_keys(pwd, crc_table);
    // Decrypt header
    let mut header_plain = [0u8; 12];
    for i in 0..12 {
        let c = target.enc_bytes[i];
        let t = zip_decrypt_byte(&keys);
        let p = c ^ t;
        header_plain[i] = p;
        zip_update_keys(&mut keys, p, crc_table);
    }
    // Check last byte
    let expected = if (target.flag & 0x8) != 0 {
        ((target.mod_time >> 8) & 0xff) as u8
    } else {
        ((target.crc >> 24) & 0xff) as u8
    };
    if header_plain[11] != expected {
        return false;
    }
    // Decrypt rest and check CRC / decompress
    let data_enc = &target.enc_bytes[12..];
    // Decrypt data
    let mut plain = Vec::with_capacity(data_enc.len());
    // Need to continue with keys after header
    for &c in data_enc {
        let t = zip_decrypt_byte(&keys);
        let p = c ^ t;
        plain.push(p);
        zip_update_keys(&mut keys, p, crc_table);
    }
    if target.method == 0 {
        // stored
        let crc = crc32(&plain, crc_table);
        return crc == target.crc;
    } else if target.method == 8 {
        // deflated: decompress
        // plain is deflated data, need to inflate
        let mut decoder = flate2::read::DeflateDecoder::new(&plain[..]);
        let mut out = Vec::new();
        match decoder.read_to_end(&mut out) {
            Ok(_) => {
                let crc = crc32(&out, crc_table);
                return crc == target.crc;
            },
            Err(_) => return false,
        }
    } else {
        // Unsupported method: just header check passed => consider true? But to match original full check, we already did header + ... For unsupported, header pass is enough?
        // We'll return true if header passed (since can't verify further)
        return true;
    }
}

fn check_aes(pwd: &[u8], target: &TargetFile) -> bool {
    let (salt_len, key_len) = match target.aes_strength { 1 => (8,16), 2 => (12,24), 3 => (16,32), _ => return false };
    let _ = (salt_len, key_len);
    let dklen = 2*key_len + 2;
    let dk = pbkdf2_hmac_sha1(pwd, &target.salt, 1000, dklen);
    if dk[dklen-2] != target.verif[0] || dk[dklen-1] != target.verif[1] {
        return false;
    }
    let auth_key = &dk[key_len .. key_len*2];
    let h = hmac_sha1(auth_key, &target.enc_data);
    // Compare first 10 bytes
    for i in 0..10 {
        if h[i] != target.auth[i] {
            return false;
        }
    }
    true
}

fn format_elapsed(elapsed: std::time::Duration) -> String {
    let secs = elapsed.as_secs();
    let millis = elapsed.subsec_millis();
    let micros = elapsed.subsec_micros() % 1000;
    let nanos = elapsed.subsec_nanos() % 1000;
    if secs > 0 {
        format!("{}s {}ms {}us {}ns", secs, millis, micros, nanos)
    } else if millis > 0 {
        format!("{}ms {}us {}ns", millis, micros, nanos)
    } else if micros > 0 {
        format!("{}us {}ns", micros, nanos)
    } else {
        format!("{}ns", nanos)
    }
}

fn s_charset() -> Vec<char> {
    // space and symbols in ASCII order, excluding alphanumerics
    let mut v = Vec::new();
    for c in 32u8..=126u8 {
        let ch = c as char;
        if ch.is_ascii_alphanumeric() { continue; }
        v.push(ch);
    }
    v
}

