// CRC32 table
fn make_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut c = i as u32;
        for _ in 0..8 {
            if c & 1 != 0 {
                c = 0xedb88320 ^ (c >> 1);
            } else {
                c >>= 1;
            }
        }
        table[i] = c;
    }
    table
}

fn crc32(data: &[u8], table: &[u32; 256]) -> u32 {
    let mut crc: u32 = 0xffffffff;
    for &b in data {
        crc = table[((crc ^ (b as u32)) & 0xff) as usize] ^ (crc >> 8);
    }
    crc ^ 0xffffffff
}

// SHA1 implementation
fn sha1(input: &[u8]) -> [u8; 20] {
    let mut h0: u32 = 0x67452301;
    let mut h1: u32 = 0xEFCDAB89;
    let mut h2: u32 = 0x98BADCFE;
    let mut h3: u32 = 0x10325476;
    let mut h4: u32 = 0xC3D2E1F0;

    let ml = (input.len() as u64) * 8;
    let mut padded = Vec::from(input);
    padded.push(0x80);
    while (padded.len() % 64) != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&ml.to_be_bytes());

    for chunk in padded.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = ((chunk[i*4] as u32) << 24) | ((chunk[i*4+1] as u32) << 16) | ((chunk[i*4+2] as u32) << 8) | (chunk[i*4+3] as u32);
        }
        for i in 16..80 {
            w[i] = (w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16]).rotate_left(1);
        }
        let mut a = h0;
        let mut b = h1;
        let mut c = h2;
        let mut d = h3;
        let mut e = h4;
        for i in 0..80 {
            let (f, k) = if i < 20 {
                ((b & c) | ((!b) & d), 0x5A827999)
            } else if i < 40 {
                (b ^ c ^ d, 0x6ED9EBA1)
            } else if i < 60 {
                ((b & c) | (b & d) | (c & d), 0x8F1BBCDC)
            } else {
                (b ^ c ^ d, 0xCA62C1D6)
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
        h4 = h4.wrapping_add(e);
    }
    let mut out = [0u8; 20];
    out[0..4].copy_from_slice(&h0.to_be_bytes());
    out[4..8].copy_from_slice(&h1.to_be_bytes());
    out[8..12].copy_from_slice(&h2.to_be_bytes());
    out[12..16].copy_from_slice(&h3.to_be_bytes());
    out[16..20].copy_from_slice(&h4.to_be_bytes());
    out
}

fn hmac_sha1(key: &[u8], data: &[u8]) -> [u8; 20] {
    let mut key_block = [0u8; 64];
    if key.len() > 64 {
        let h = sha1(key);
        key_block[..20].copy_from_slice(&h);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }
    let mut ipad = [0x36u8; 64];
    let mut opad = [0x5cu8; 64];
    for i in 0..64 {
        ipad[i] ^= key_block[i];
        opad[i] ^= key_block[i];
    }
    let mut inner = Vec::with_capacity(64 + data.len());
    inner.extend_from_slice(&ipad);
    inner.extend_from_slice(data);
    let inner_hash = sha1(&inner);
    let mut outer = Vec::with_capacity(64 + 20);
    outer.extend_from_slice(&opad);
    outer.extend_from_slice(&inner_hash);
    sha1(&outer)
}

fn pbkdf2_hmac_sha1(password: &[u8], salt: &[u8], iterations: u32, dklen: usize) -> Vec<u8> {
    let hlen = 20;
    let l = (dklen + hlen - 1) / hlen;
    let mut dk = Vec::with_capacity(l * hlen);
    for i in 1..=l {
        let mut salt_block = Vec::with_capacity(salt.len() + 4);
        salt_block.extend_from_slice(salt);
        salt_block.extend_from_slice(&(i as u32).to_be_bytes());
        let mut u = hmac_sha1(password, &salt_block);
        let mut t = u;
        for _ in 1..iterations {
            u = hmac_sha1(password, &u);
            for j in 0..hlen {
                t[j] ^= u[j];
            }
        }
        dk.extend_from_slice(&t);
    }
    dk.truncate(dklen);
    dk
}

// ZipCrypto
fn init_zip_keys(pwd: &[u8], table: &[u32; 256]) -> [u32; 3] {
    let mut k0: u32 = 0x12345678;
    let mut k1: u32 = 0x23456789;
    let mut k2: u32 = 0x34567890;
    for &b in pwd {
        k0 = table[((k0 ^ (b as u32)) & 0xff) as usize] ^ (k0 >> 8);
        k1 = k1.wrapping_add(k0 & 0xff).wrapping_mul(0x08088405).wrapping_add(1);
        k2 = table[((k2 ^ (k1 >> 24)) & 0xff) as usize] ^ (k2 >> 8);
    }
    [k0, k1, k2]
}

fn zip_decrypt_byte(keys: &[u32; 3]) -> u8 {
    let temp = keys[2] | 2;
    (((temp.wrapping_mul(temp ^ 1)) >> 8) & 0xff) as u8
}

fn zip_update_keys(keys: &mut [u32; 3], b: u8, table: &[u32; 256]) {
    keys[0] = table[((keys[0] ^ (b as u32)) & 0xff) as usize] ^ (keys[0] >> 8);
    keys[1] = keys[1].wrapping_add(keys[0] & 0xff).wrapping_mul(0x08088405).wrapping_add(1);
    keys[2] = table[((keys[2] ^ (keys[1] >> 24)) & 0xff) as usize] ^ (keys[2] >> 8);
}

// Zip structures
struct ZipEntryInfo {
    file_name: Vec<u8>,
    flag: u16,
    method: u16,
    crc: u32,
    comp_size: u32,
    uncomp_size: u32,
