fn read_u16_le(data: &[u8], pos: usize) -> Option<u16> {
    if pos + 2 > data.len() { return None; }
    Some(u16::from_le_bytes([data[pos], data[pos+1]]))
}
fn read_u32_le(data: &[u8], pos: usize) -> Option<u32> {
    if pos + 4 > data.len() { return None; }
    Some(u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]))
}

fn parse_zip(data: &[u8]) -> Result<ZipFileData, String> {
    // Find EOCD: search backwards for PK\x05\x06
    if data.len() < 22 {
        return Err("Could not find EOCD".to_string());
    }
    let mut eocd_pos: Option<usize> = None;
    // EOCD can have comment up to 65535, so search last 65557 bytes
    let search_start = if data.len() > 65557 + 22 { data.len() - (65557 + 22) } else { 0 };
    for pos in (search_start..data.len().saturating_sub(4)).rev() {
        if data[pos] == 0x50 && data[pos+1] == 0x4b && data[pos+2] == 0x05 && data[pos+3] == 0x06 {
            // Check comment len matches
            if pos + 22 > data.len() { continue; }
            let comment_len = u16::from_le_bytes([data[pos+20], data[pos+21]]) as usize;
            if pos + 22 + comment_len == data.len() {
                eocd_pos = Some(pos);
                break;
            }
        }
    }
    let eocd_pos = match eocd_pos {
        Some(p) => p,
        None => return Err("Could not find EOCD".to_string()),
    };
    // Parse EOCD
    if eocd_pos + 22 > data.len() {
        return Err("Unexpected end of zip::spec::Zip32CDEBlock".to_string());
    }
    let disk_num = read_u16_le(data, eocd_pos+4).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_disk = read_u16_le(data, eocd_pos+6).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_entries_disk = read_u16_le(data, eocd_pos+8).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_entries_total = read_u16_le(data, eocd_pos+10).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_size = read_u32_le(data, eocd_pos+12).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    let cd_offset = read_u32_le(data, eocd_pos+16).ok_or("Unexpected end of zip::spec::Zip32CDEBlock".to_string())?;
    // Ignore disk checks for simplicity (assume single disk)
    let _ = (disk_num, cd_disk, cd_entries_disk);
    let count = cd_entries_total as usize;
    let mut entries = Vec::new();
    let mut pos = cd_offset as usize;
    for _ in 0..count {
        if pos + 46 > data.len() {
            return Err("Unexpected end of zip::types::ZipCentralEntryBlock".to_string());
        }
        if !(data[pos]==0x50 && data[pos+1]==0x4b && data[pos+2]==0x01 && data[pos+3]==0x02) {
            return Err("Unexpected end of zip::types::ZipCentralEntryBlock".to_string());
        }
        let flag = read_u16_le(data, pos+8).unwrap();
        let method = read_u16_le(data, pos+10).unwrap();
        let mod_time = read_u16_le(data, pos+12).unwrap();
        let mod_date = read_u16_le(data, pos+14).unwrap();
        let crc = read_u32_le(data, pos+16).unwrap();
        let comp_size = read_u32_le(data, pos+20).unwrap();
        let uncomp_size = read_u32_le(data, pos+24).unwrap();
        let fn_len = read_u16_le(data, pos+28).unwrap() as usize;
        let extra_len = read_u16_le(data, pos+30).unwrap() as usize;
        let comment_len = read_u16_le(data, pos+32).unwrap() as usize;
        let local_offset = read_u32_le(data, pos+42).unwrap();
        if pos + 46 + fn_len + extra_len + comment_len > data.len() {
            return Err("Unexpected end of zip::types::ZipCentralEntryBlock".to_string());
        }
        let file_name = data[pos+46..pos+46+fn_len].to_vec();
        // skip extra and comment
        pos += 46 + fn_len + extra_len + comment_len;
        entries.push(ZipEntryInfo { file_name, flag, method, crc, comp_size, uncomp_size, local_offset, mod_time, mod_date });
    }
    Ok(ZipFileData { entries })
}

struct TargetFile {
