}

fn get_target(data: &[u8], zip: &ZipFileData, file_number: usize) -> Result<TargetFile, String> {
    if file_number >= zip.entries.len() {
        return Err(format!("File number not found within archive error - '{}'", file_number));
    }
    let e = &zip.entries[file_number];
    let file_name_str = String::from_utf8_lossy(&e.file_name).to_string();
    if (e.flag & 0x1) == 0 {
        return Err(format!("Invalid zip file error - the selected file in the archive is not encrypted (file_number:{} file_name:{})", file_number, file_name_str));
    }
    // Check if AES (method 99)
    if e.method == 99 {
        // Need to parse local header to get extra and enc data
        let local_off = e.local_offset as usize;
        if local_off + 30 > data.len() {
            return Err("Invalid local file header".to_string());
        }
        if !(data[local_off]==0x50 && data[local_off+1]==0x4b && data[local_off+2]==0x03 && data[local_off+3]==0x04) {
            return Err("Invalid local file header".to_string());
        }
        let local_flag = read_u16_le(data, local_off+8).unwrap();
        let local_method = read_u16_le(data, local_off+10).unwrap();
        let _local_crc = read_u32_le(data, local_off+14).unwrap();
        let local_comp = read_u32_le(data, local_off+18).unwrap();
        let _local_uncomp = read_u32_le(data, local_off+22).unwrap();
        let fn_len = read_u16_le(data, local_off+26).unwrap() as usize;
        let extra_len = read_u16_le(data, local_off+28).unwrap() as usize;
        if local_off + 30 + fn_len + extra_len > data.len() {
            return Err("Invalid local file header".to_string());
        }
        let extra = &data[local_off+30+fn_len .. local_off+30+fn_len+extra_len];
        // Parse AES extra: find 0x9901
        let mut strength: Option<u8> = None;
        let mut aes_method: Option<u16> = None;
        let mut p = 0;
        while p + 4 <= extra.len() {
            let hid = u16::from_le_bytes([extra[p], extra[p+1]]);
            let sz = u16::from_le_bytes([extra[p+2], extra[p+3]]) as usize;
            if p + 4 + sz > extra.len() { break; }
            if hid == 0x9901 {
                if sz >= 7 {
                    // version 2 bytes, vendor 2 bytes, strength 1, method 2
                    let ver = u16::from_le_bytes([extra[p+4], extra[p+5]]);
                    let _vendor = &extra[p+6..p+8];
                    let s = extra[p+8];
                    let m = u16::from_le_bytes([extra[p+9], extra[p+10]]);
                    let _ = ver;
                    strength = Some(s);
                    aes_method = Some(m);
                }
                break;
            }
            p += 4 + sz;
        }
        let strength = strength.ok_or("Invalid AES extra".to_string())?;
        let aes_method = aes_method.unwrap_or(0);
        let salt_len = match strength { 1 => 8, 2 => 12, 3 => 16, _ => return Err("Invalid AES strength".to_string()) };
        // Use central's comp size? For AES, local comp should equal central comp? Use local_comp if non-zero else central?
        // Actually for descriptor, local may be 0. Use central if local is 0?
        let comp_size = if local_comp != 0 { local_comp } else { e.comp_size } as usize;
        let enc_start = local_off + 30 + fn_len + extra_len;
        if enc_start + comp_size > data.len() {
            return Err("Invalid AES data".to_string());
        }
        let enc = &data[enc_start .. enc_start+comp_size];
        if enc.len() < salt_len + 2 + 10 {
            return Err("Invalid AES data".to_string());
        }
        let salt = enc[..salt_len].to_vec();
        let verif = [enc[salt_len], enc[salt_len+1]];
        let auth_start = enc.len() - 10;
        let enc_data = enc[salt_len+2 .. auth_start].to_vec();
        let mut auth = [0u8; 10];
        auth.copy_from_slice(&enc[auth_start..]);
        let _ = (local_flag, local_method);
        Ok(TargetFile { is_aes: true, aes_strength: strength, aes_method, salt, verif, enc_data, auth, flag: e.flag, method: e.method, crc: e.crc, mod_time: e.mod_time, enc_bytes: Vec::new(), file_name_str })
    } else {
        // ZipCrypto
        let local_off = e.local_offset as usize;
        if local_off + 30 > data.len() {
            return Err("Invalid local file header".to_string());
        }
        if !(data[local_off]==0x50 && data[local_off+1]==0x4b && data[local_off+2]==0x03 && data[local_off+3]==0x04) {
            return Err("Invalid local file header".to_string());
        }
        let _local_flag = read_u16_le(data, local_off+8).unwrap();
        let _local_method = read_u16_le(data, local_off+10).unwrap();
        let local_crc = read_u32_le(data, local_off+14).unwrap();
        let local_comp = read_u32_le(data, local_off+18).unwrap();
        let _local_uncomp = read_u32_le(data, local_off+22).unwrap();
        let fn_len = read_u16_le(data, local_off+26).unwrap() as usize;
        let extra_len = read_u16_le(data, local_off+28).unwrap() as usize;
        let local_mod_time = read_u16_le(data, local_off+12).unwrap();
        if local_off + 30 + fn_len + extra_len > data.len() {
            return Err("Invalid local file header".to_string());
        }
        // Determine comp size: if data descriptor (flag bit 3), local sizes are 0, use central
        let use_descriptor = (e.flag & 0x8) != 0;
        let comp_size = if use_descriptor || local_comp == 0 { e.comp_size } else { local_comp } as usize;
        let crc_val = if use_descriptor || local_crc == 0 { e.crc } else { local_crc };
        // For descriptor, header check uses time, not crc. Need mod_time: use local or central? Use e.mod_time? Both should match? Use e.mod_time
        let enc_start = local_off + 30 + fn_len + extra_len;
        if enc_start + comp_size > data.len() {
            return Err("Invalid ZipCrypto data".to_string());
        }
        let enc_bytes = data[enc_start .. enc_start+comp_size].to_vec();
        let _ = local_mod_time;
        Ok(TargetFile { is_aes: false, aes_strength: 0, aes_method: 0, salt: Vec::new(), verif: [0,0], enc_data: Vec::new(), auth: [0;10], flag: e.flag, method: e.method, crc: crc_val, mod_time: e.mod_time, enc_bytes, file_name_str })
    }
}

fn check_zipcrypto(pwd: &[u8], target: &TargetFile, crc_table: &[u32; 256]) -> bool {
    if target.enc_bytes.len() < 12 {
        return false;
    }
    let mut keys = init_zip_keys(pwd, crc_table);
    // Decrypt header
    let mut header_plain = [0u8; 12];
    for i in 0..12 {
        let c = target.enc_bytes[i];
        let t = zip_decrypt_byte(&keys);
        let p = c ^ t;
        header_plain[i] = p;
        zip_update_keys(&mut keys, p, crc_table);
    }
    // Check last byte
    let expected = if (target.flag & 0x8) != 0 {
        ((target.mod_time >> 8) & 0xff) as u8
    } else {
        ((target.crc >> 24) & 0xff) as u8
    };
    if header_plain[11] != expected {
        return false;
    }
    // Decrypt rest and check CRC / decompress
    let data_enc = &target.enc_bytes[12..];
    // Decrypt data
    let mut plain = Vec::with_capacity(data_enc.len());
    // Need to continue with keys after header
    for &c in data_enc {
        let t = zip_decrypt_byte(&keys);
        let p = c ^ t;
        plain.push(p);
        zip_update_keys(&mut keys, p, crc_table);
    }
    if target.method == 0 {
        // stored
        let crc = crc32(&plain, crc_table);
        return crc == target.crc;
    } else if target.method == 8 {
        // deflated: decompress
        // plain is deflated data, need to inflate
        let mut decoder = flate2::read::DeflateDecoder::new(&plain[..]);
        let mut out = Vec::new();
        match decoder.read_to_end(&mut out) {
            Ok(_) => {
                let crc = crc32(&out, crc_table);
                return crc == target.crc;
            },
            Err(_) => return false,
        }
    } else {
        // Unsupported method: just header check passed => consider true? But to match original full check, we already did header + ... For unsupported, header pass is enough?
        // We'll return true if header passed (since can't verify further)
        return true;
    }
}

fn check_aes(pwd: &[u8], target: &TargetFile) -> bool {
    let (salt_len, key_len) = match target.aes_strength { 1 => (8,16), 2 => (12,24), 3 => (16,32), _ => return false };
    let _ = (salt_len, key_len);
    let dklen = 2*key_len + 2;
    let dk = pbkdf2_hmac_sha1(pwd, &target.salt, 1000, dklen);
    if dk[dklen-2] != target.verif[0] || dk[dklen-1] != target.verif[1] {
        return false;
    }
    let auth_key = &dk[key_len .. key_len*2];
    let h = hmac_sha1(auth_key, &target.enc_data);
    // Compare first 10 bytes
    for i in 0..10 {
        if h[i] != target.auth[i] {
            return false;
        }
    }
    true
}

fn format_elapsed(elapsed: std::time::Duration) -> String {
    let secs = elapsed.as_secs();
    let millis = elapsed.subsec_millis();
    let micros = elapsed.subsec_micros() % 1000;
    let nanos = elapsed.subsec_nanos() % 1000;
    if secs > 0 {
        format!("{}s {}ms {}us {}ns", secs, millis, micros, nanos)
    } else if millis > 0 {
        format!("{}ms {}us {}ns", millis, micros, nanos)
    } else if micros > 0 {
        format!("{}us {}ns", micros, nanos)
    } else {
        format!("{}ns", nanos)
    }
}

fn s_charset() -> Vec<char> {
    // space and symbols in ASCII order, excluding alphanumerics
    let mut v = Vec::new();
    for c in 32u8..=126u8 {
        let ch = c as char;
        if ch.is_ascii_alphanumeric() { continue; }
        v.push(ch);
    }
    v
}

