fn zip_update_keys(keys: &mut [u32; 3], b: u8, table: &[u32; 256]) {
    keys[0] = table[((keys[0] ^ (b as u32)) & 0xff) as usize] ^ (keys[0] >> 8);
    keys[1] = keys[1].wrapping_add(keys[0] & 0xff).wrapping_mul(0x08088405).wrapping_add(1);
