fn parse_zip(data: &[u8]) -> Result<ZipFileData, String> {
    // Find EOCD: search backwards for PK\x05\x06
    if data.len() < 22 {
        return Err("Could not find EOCD".to_string());
    }
    let mut eocd_pos: Option<usize> = None;
