fn dict_attack(passwords: Vec<Vec<u8>>, target: Arc<TargetFile>, workers: usize, crc_table: &[u32; 256]) -> Option<Vec<u8>> {
    if passwords.is_empty() {
        return None;
    }
    let found_flag = Arc::new(AtomicBool::new(false));
    let result: Arc<std::sync::Mutex<Option<Vec<u8>>>> = Arc::new(std::sync::Mutex::new(None));
    // Shard passwords among workers
    let chunk = (passwords.len() + workers - 1) / workers;
    let passwords_arc = Arc::new(passwords);
    let mut handles = Vec::new();
    for i in 0..workers {
        let start = i * chunk;
        if start >= passwords_arc.len() { break; }
        let end = std::cmp::min(start + chunk, passwords_arc.len());
        let pw_arc = Arc::clone(&passwords_arc);
        let tgt = Arc::clone(&target);
        let flag = Arc::clone(&found_flag);
        let res = Arc::clone(&result);
        let table = crc_table.clone();
        // Need to copy table? crc_table is [u32;256], clone is cheap. Or use Arc.
        let handle = std::thread::Builder::new().name(format!("worker-{}", i+1)).spawn(move || {
            for idx in start..end {
                if flag.load(Ordering::Relaxed) { break; }
                let pwd = &pw_arc[idx];
                let ok = if tgt.is_aes {
                    check_aes(pwd, &tgt)
                } else {
                    check_zipcrypto(pwd, &tgt, &table)
                };
                if ok {
                    // Try to set result if not already set
                    let mut guard = res.lock().unwrap();
                    if guard.is_none() {
                        *guard = Some(pwd.clone());
                        flag.store(true, Ordering::Relaxed);
                    }
                    break;
                }
            }
        }).unwrap();
        handles.push(handle);
    }
    for h in handles { let _ = h.join(); }
    let guard = result.lock().unwrap();
    guard.clone()
}

